import { Component, Input, OnInit } from '@angular/core';
import { NgbActiveModal } from '@ng-bootstrap/ng-bootstrap';
import { ModalTypeEnums } from 'src/app/core/enums/modal.enums';
import {  Program, Publisher, WeeklyProgram } from 'src/app/core/interfaces/reuniones.interface';

@Component({
    selector: 'app-modal',
    templateUrl: './modal-container.component.html',
    styleUrls: ['./modal-container.component.scss'],
    standalone: false
})
export class ModalContainerComponent implements OnInit {
  valueExchange($event: any) {
    this.values = $event
  }
  @Input() titulo!: string;
  @Input() mensaje!: string;
  @Input() LabelButton: string = 'Ok';
  @Input() urlSrc!: string;
  @Input() Icon: string = '';
  @Input() textButton: string = 'Crear';
  @Input() modalType: string = 'info';
  @Input() assignment!: WeeklyProgram;
  @Input() program!: Program;
  @Input() song!: string;
  @Input() hour?: unknown;
  @Input() errorMessage!: string;
  @Input() errorTitle!: string;
  @Input() errorType!: string;
  @Input() title!: string;
  @Input() subTitle!: string;
  @Input() assignmentType!: string;
  @Input() programSelection: boolean = false;
  @Input() brothersOnly: boolean = false;
  @Input() selectionTitle?: string;
  @Input() currentPublisher?: Publisher | null;
  @Input() week?: string | number | null;
  @Input() sectionMeeting!: string;
  @Input() isModal: boolean = true;
  @Input() type: string = 'responsible' ;
  @Input() printOrientation: "normal" | "landscape" = "normal";
  @Input() room: string = 'A' ;

  public typeOfModals = ModalTypeEnums

  private values: any | null = <any>{};
  constructor(public activeModal: NgbActiveModal) { }

  ngOnInit(): void {
    // This is intentional
  }

  onClick(opcion: any) {
    this.activeModal.close(opcion);
  }

  hasCloseControl(): boolean {
    return [
      ModalTypeEnums.SELECT_HOUR,
      ModalTypeEnums.TITLE_AND_TIME,
      ModalTypeEnums.CHANGE_SONGS,
      ModalTypeEnums.ERROR,
      ModalTypeEnums.SUCCESS,
      ModalTypeEnums.LOADER,
      ModalTypeEnums.INFO,
    ].includes(this.modalType as ModalTypeEnums);
  }

  close() {
    this.activeModal.close('close');
  }
  onClicked(item: unknown) {
    this.activeModal.close(item);
  }

}
